do $$
declare
  v_total int;
  v_bad_subject int;
  v_null_ratio int;
  v_task_verb int;
  v_judgement int;
  v_medium int;
  v_easy int;
  v_hard int;
begin
  select count(*) into v_total from app.content_item_difficulty
    where proposal_run = 'work_order_J0_resume_2026_09_24';
  if v_total <> 118 then raise exception 'J0 load: expected 118 rows, got %', v_total; end if;

  select count(*) into v_bad_subject from app.content_item_difficulty cid
    where cid.proposal_run = 'work_order_J0_resume_2026_09_24'
    and not exists (
      select 1 from app.content_item_versions civ
      join app.content_items ci on ci.id = civ.content_item_id
      join app.exam_pack_versions epv on epv.id = ci.exam_pack_version_id
      join app.exam_packs ep on ep.id = epv.exam_pack_id
      where civ.id = cid.content_item_version_id and civ.status = 'published'
        and ep.exam_code = 'ap_biology');
  if v_bad_subject <> 0 then raise exception 'J0 load: % rows are not published Biology items', v_bad_subject; end if;

  select count(*) filter (where attainment_ratio is null),
         count(*) filter (where basis = 'calibrated_task_verb'),
         count(*) filter (where basis = 'calibrated_judgement'),
         count(*) filter (where difficulty = 'Medium'),
         count(*) filter (where difficulty = 'Easy'),
         count(*) filter (where difficulty = 'Hard')
    into v_null_ratio, v_task_verb, v_judgement, v_medium, v_easy, v_hard
    from app.content_item_difficulty where proposal_run = 'work_order_J0_resume_2026_09_24';

  if v_null_ratio <> 47 then raise exception 'J0 load: expected 47 null ratios, got %', v_null_ratio; end if;
  if v_task_verb <> 81 then raise exception 'J0 load: expected 81 calibrated_task_verb, got %', v_task_verb; end if;
  if v_judgement <> 37 then raise exception 'J0 load: expected 37 calibrated_judgement, got %', v_judgement; end if;
  if v_medium <> 75 or v_easy <> 23 or v_hard <> 20 then
    raise exception 'J0 load: band distribution mismatch (Medium % Easy % Hard %)', v_medium, v_easy, v_hard;
  end if;
end $$;

